// DefaultExploration is the UCB1 exploration constant (sqrt 2).
const DefaultExploration = 1.4142135623730951

// RecombinationProbability is the chance an expansion step picks the
// recombination branch instead of a single-parent rewrite, once the tree has
// at least DefaultTopK valid candidates.
const RecombinationProbability = 0.25

// DefaultTopK is the number of top candidates fed to the recombination prompt.
const DefaultTopK = 3

// MaxBlockBytes caps each untrusted block (parent source, ideas, candidates
// in recombination) before it is wrapped and framed. Long blobs can blow the
// model's context budget or bury earlier instructions; this is a defensive
// default, not a guarantee — callers handling very large sources should
// truncate upstream too.
const MaxBlockBytes = 16384

// Task carries the inputs to an ERA run. Higher=true maximizes Score;
// Higher=false minimizes (e.g. ns/op). Ideas is optional external research
// context injected into every rewrite prompt and wrapped as untrusted data.
type Task struct {
	Description string
	Baseline    string
	Higher      bool
	Ideas       []string
}

// Candidate is one node in the search tree. Parent is the index of the
// candidate this one was rewritten from (-1 for the root and for any
// recombination result). Valid=false means the scorer rejected this
// candidate; invalid candidates do not participate in selection. Visits is
// the UCB1 visit count, incremented each time the node is chosen as a
// parent for expansion.
type Candidate struct {
	Source string
	Score  float64
	Parent int
	Valid  bool
	Visits int
}

// Run executes the propose -> score -> select loop for `budget` expansion
// rounds and returns the best valid candidate, the full tree, and an error
// only on a setup failure (per-candidate failures are absorbed into
// Valid=false rather than aborting the run). The loop checks `h.Ctx.Err()`
// at the top of each round and exits cleanly on cancellation — pass
// `ctx.Background()` if you don't need cancellation.
func Run(h ctxpkg.Handle, ask func(string) (string, error), task Task, score func(string) (float64, error), budget int) (Candidate, []Candidate, error) {
	tree := []Candidate{}
	rootScore, rootErr := score(task.Baseline)
	root := Candidate{Source: task.Baseline, Score: rootScore, Parent: -1, Valid: rootErr == nil, Visits: 0}
	tree = append(tree, root)
	for range budget {
		if h.Ctx.Err() != nil {
			break
		}
		parentIdx := SelectFUTS(tree, task.Higher, DefaultExploration)
		if parentIdx < 0 {
			break
		}
		useRecombine := countValid(tree) >= DefaultTopK && rand.Float64() < RecombinationProbability
		var proposal string
		var proposeErr error
		if useRecombine {
			proposal, proposeErr = ProposeRecombination(ask, task, topK(tree, task.Higher, DefaultTopK))
		} else {
			proposal, proposeErr = ProposeRewrite(ask, task, tree[parentIdx], best(tree, task.Higher))
		}
		tree[parentIdx].Visits += 1
		if proposeErr != nil {
			continue
		}
		candScore, candErr := score(proposal)
		candParent := func() int {
			if useRecombine {
				return -1
			} else {
				return parentIdx
			}
		}()
		cand := Candidate{Source: proposal, Score: candScore, Parent: candParent, Valid: candErr == nil, Visits: 0}
		tree = append(tree, cand)
	}
	return best(tree, task.Higher), tree, nil
}

// SelectFUTS picks the next parent to expand via flat UCB1 over valid
// candidates. Returns -1 when no valid candidates exist. exploration is the
// UCB constant (DefaultExploration is sqrt(2)). When higher=false, scores
// are inverted before normalization so the loop minimizes.
func SelectFUTS(tree []Candidate, higher bool, exploration float64) int {
	if len(tree) == 0 {
		return -1
	}
	totalVisits := 0
	validCount := 0
	for _, c := range tree {
		if c.Valid {
			validCount += 1
			totalVisits = totalVisits + c.Visits + 1
		}
	}
	if validCount == 0 {
		return -1
	}
	lo, hi := minMaxValidScore(tree)
	span := hi - lo
	if span == 0.0 {
		span = 1.0
	}
	bestIdx := -1
	bestUCB := math.Inf(-1)
	for idx := range len(tree) {
		c := tree[idx]
		if !c.Valid {
			continue
		}
		norm := (c.Score - lo) / span
		if !higher {
			norm = 1.0 - norm
		}
		ucb := norm + exploration*math.Sqrt(math.Log(float64(totalVisits))/float64(c.Visits+1))
		if ucb > bestUCB {
			bestUCB = ucb
			bestIdx = idx
		}
	}
	return bestIdx
}

// ProposeRewrite asks the model to rewrite a single parent toward a better
// score. Untrusted strings are truncated to MaxBlockBytes and wrapped via
// stdlib/llm/safe before framing.
func ProposeRewrite(ask func(string) (string, error), task Task, parent Candidate, best Candidate) (string, error) {
	direction := func() string {
		if task.Higher {
			return "MAXIMIZE"
		} else {
			return "MINIMIZE"
		}
	}()
	instructions := fmt.Sprintf("You are improving a piece of source code to %v a numeric score.\nProblem: %v\nParent score: %v\nCurrent best score: %v\nReturn ONLY the complete new source. No prose, explanations, or markdown fences.", direction, task.Description, parent.Score, best.Score)
	blocks := []string{safe.Wrap("PARENT_SOURCE", safe.Truncate(parent.Source, MaxBlockBytes))}
	if len(task.Ideas) != 0 {
		ideas := safe.Truncate(strpkg.Join(task.Ideas, "\n---\n"), MaxBlockBytes)
		blocks = append(blocks, safe.Wrap("IDEAS", ideas))
	}
	prompt := safe.Frame(instructions, blocks)
	raw, err := ask(prompt)
	if err != nil {
		return "", err
	}
	return stripFences(raw), nil
}

// ProposeRecombination asks the model to synthesize a hybrid from the top-K
// candidates so far. `top` must already be sorted best-first by the caller.
func ProposeRecombination(ask func(string) (string, error), task Task, top []Candidate) (string, error) {
	direction := func() string {
		if task.Higher {
			return "MAXIMIZE"
		} else {
			return "MINIMIZE"
		}
	}()
	instructions := fmt.Sprintf("Synthesize a hybrid source that combines the strongest aspects of the candidates below to %v the score.\nProblem: %v\nReturn ONLY the complete new source. No prose, explanations, or markdown fences.", direction, task.Description)
	blocks := []string{}
	for i := range len(top) {
		c := top[i]
		label := fmt.Sprintf("CANDIDATE_%v_SCORE_%v", i+1, c.Score)
		blocks = append(blocks, safe.Wrap(label, safe.Truncate(c.Source, MaxBlockBytes)))
	}
	if len(task.Ideas) != 0 {
		ideas := safe.Truncate(strpkg.Join(task.Ideas, "\n---\n"), MaxBlockBytes)
		blocks = append(blocks, safe.Wrap("IDEAS", ideas))
	}
	prompt := safe.Frame(instructions, blocks)
	raw, err := ask(prompt)
	if err != nil {
		return "", err
	}
	return stripFences(raw), nil
}

// BuildScore writes the candidate to a temp .kuki file and runs
// `kukicha build --json --skip-build` on it. Returns 1.0 if the candidate
// parses+typechecks, otherwise an error. Use for "smoke test" tasks where
// the goal is producing a compiling program at all.
func BuildScore(source string) (float64, error) {
	dir, cleanup, dirErr := files.TempDirAuto("era-build-")
	if dirErr != nil {
		return 0.0, dirErr
	}
	defer cleanup()
	path := files.Join(dir, "candidate.kuki")
	err := files.WriteString(source, path)
	if err != nil {
		return 0, err
	}
	shell.Output("kukicha", "build", "--json", "--skip-build", path)
	return 1.0, nil
}

// RunScore builds and runs the candidate, then hands program stdout to
// `metric` to extract a numeric score. The metric callback owns parsing —
// most callers will look for a single number on the last line.
func RunScore(source string, metric func(string) (float64, error)) (float64, error) {
	dir, cleanup, dirErr := files.TempDirAuto("era-run-")
	if dirErr != nil {
		return 0.0, dirErr
	}
	defer cleanup()
	path := files.Join(dir, "candidate.kuki")
	err := files.WriteString(source, path)
	if err != nil {
		return 0, err
	}
	out, err_1 := shell.Output("kukicha", "run", path)
	if err_1 != nil {
		return 0, err_1
	}
	return metric(out)
}

// BenchScore runs `go test -bench {benchName} -benchmem -count=1 -run=^$`
// inside a workspace materialized by `setup`. Setup receives the candidate
// source and returns the directory to run the bench in (e.g. by writing
// the source into a clone of the package being tuned). The score is the
// parsed ns/op of the first matching benchmark line.
func BenchScore(source string, setup func(string) (string, error), benchName string) (float64, error) {
	workDir, err := setup(source)
	if err != nil {
		return 0, err
	}
	// pipe step 1: Output(...)
	out, err_3 := shell.New("go", "test", "-bench", benchName, "-benchmem", "-count=1", "-run=^$", "./...").Dir(workDir).Output()
	if err_3 != nil {
		return 0, err_3
	}
	return parseBenchNsPerOp(out, benchName)
}

// StripFences removes a leading/trailing triple-backtick fence (optionally
// language-tagged) from a model response. Exposed for tests and for callers
// that want to normalize ask() output before scoring.
func StripFences(s string) string {
	return stripFences(s)
}

func stripFences(s string) string {
	s = strpkg.TrimSpace(s)
	if !strpkg.HasPrefix(s, "```") {
		return s
	}
	lines := strpkg.Split(s, "\n")
	if len(lines) < 2 {
		return s
	}
	lines = lines[1:]
	if len(lines) != 0 && strpkg.HasPrefix(lines[len(lines)-1], "```") {
		lines = lines[:len(lines)-1]
	}
	return strpkg.TrimSpace(strpkg.Join(lines, "\n"))
}

func countValid(tree []Candidate) int {
	n := 0
	for _, c := range tree {
		if c.Valid {
			n += 1
		}
	}
	return n
}

func minMaxValidScore(tree []Candidate) (float64, float64) {
	lo := math.Inf(1)
	hi := math.Inf(-1)
	for _, c := range tree {
		if !c.Valid {
			continue
		}
		if c.Score < lo {
			lo = c.Score
		}
		if c.Score > hi {
			hi = c.Score
		}
	}
	return lo, hi
}

func best(tree []Candidate, higher bool) Candidate {
	var bestC Candidate
	found := false
	for _, c := range tree {
		if !c.Valid {
			continue
		}
		if !found {
			bestC = c
			found = true
			continue
		}
		if higher && c.Score > bestC.Score {
			bestC = c
		}
		if !higher && c.Score < bestC.Score {
			bestC = c
		}
	}
	return bestC
}

func topK(tree []Candidate, higher bool, k int) []Candidate {
	valid := []Candidate{}
	for _, c := range tree {
		if c.Valid {
			valid = append(valid, c)
		}
	}
	valid = sort.By(valid, func(a Candidate, b Candidate) bool {
		return func() bool {
			if higher {
				return a.Score > b.Score
			} else {
				return a.Score < b.Score
			}
		}()
	})
	if len(valid) > k {
		valid = valid[:k]
	}
	return valid
}

func parseBenchNsPerOp(out string, benchName string) (float64, error) {
	prefix := fmt.Sprintf("Benchmark%v", benchName)
	for _, line := range strpkg.Lines(out) {
		if !strpkg.HasPrefix(line, prefix) {
			continue
		}
		fields := strpkg.Fields(line)
		for i := range len(fields) {
			if fields[i] == "ns/op" && i > 0 {
				return parse.Float64(fields[i-1])
			}
		}
	}
	return 0.0, fmt.Errorf("no benchmark line matched %v", benchName)
}
